// Sensor settings belong to the walk: edit them on the Recorded walk node.
const sensors = input['sensors.json'][0];
const valid = raw => raw >= sensors.tof_min_raw && raw <= sensors.tof_max_raw;
return (input['range.csv'] || []).map(row => ({
  seconds: row.pi_read_end_ns / 1e9,
  raw: row.tof_raw,
  metres: valid(row.tof_raw) ? row.tof_raw / sensors.tof_counts_per_metre : null
}));
